pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 randomSeed) public {
        // Use the seed to influence block.timestamp and block.difficulty so the fuzzer can explore both branches.
        // Bound to avoid overflow in the low-level arithmetic of the original contract (though it uses transfer,
        // which has a gas stipend, we keep the range reasonable).
        randomSeed = bound(randomSeed, 1, type(uint256).max);
        vm.warp(randomSeed % 1e12);
        vm.roll(randomSeed % 1e12);

        // Record state before play
        uint256 potBefore = c.pot();

        // Give the caller exactly TICKET_AMOUNT ether
        address player = address(0x1234);
        vm.deal(player, 10 ether);
        vm.prank(player);

        bool ok = true;
        try c.play{value: 10}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Property:
        // If the call succeeded, pot must be 0 (winner was selected and pot was paid out/reset).
        // If the call reverted, pot must equal potBefore + 10 (the deposit was added before revert).
        // The bug breaks the second branch: it sets pot = 0 unconditionally, so after a revert pot stays 0.
        if (ok) {
            assertTrue(c.pot() == 0);
        } else {
            assertTrue(c.pot() == potBefore + 10);
        }
    }
}

