import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint constant TICKET_AMOUNT = 10 ether;
    uint256 initialPot;

    function setUp() public {
        c = new C();
        // Set initial bank to some address with no special logic
        // Bank is already set to the deployer in constructor
    }

    function testFuzz_property(uint256 numCalls) public {
        // Admissible domain: at least one call, at most 5 to keep state exploration reasonable
        bound(numCalls, 1, 5);

        // Track expected pot based on calls made
        uint256 expectedPot = 0;
        bool allSucceeded = true;

        for (uint256 i = 0; i < numCalls; i++) {
            address caller = address(uint160(uint256(keccak256(abi.encodePacked("caller", i)))));
            vm.deal(caller, TICKET_AMOUNT);
            vm.prank(caller);
            try c.play{value: TICKET_AMOUNT}() {
                // Call succeeded: either win (pot reset to 0 after payout) or nothing (random != 0)
                // In reference C, a successful call that does not pay out still adds TICKET_AMOUNT to pot
                // Since we cannot predict random outcome, we cannot compute expectedPot without knowing random.
                // The property must hold for all inputs regardless of random.
            } catch {
                allSucceeded = false;
                break;
            }
        }

        // General rule: after any sequence of calls, if no call reverted,
        // the pot must equal the total ether sent in (numCalls * TICKET_AMOUNT) minus any payouts.
        // Payouts only happen on random == 0, and they reset pot to 0.
        // In reference C, pot is incremented by TICKET_AMOUNT on every non-reverting call,
        // and reset to 0 only on a win (with payout).
        // In buggy M, pot is reset to 0 on every call regardless of outcome,
        // so accumulated pot is lost, and the invariant fails.

        // We assert a stronger invariant that holds for reference C:
        // After any sequence of non-reverting play() calls, the pot is either
        // (numCalls * TICKET_AMOUNT) if no win ever occurred, or some value less
        // due to resets. But we need a definitive assertion.

        // The key difference: in reference C, if a call does not revert,
        // pot is increased by TICKET_AMOUNT (or reset to 0 on win).
        // In buggy M, pot is set to 0 before the win check, so pot is always 0
        // after any non-reverting call, regardless of whether a win occurred.

        // Universal property for C: if play() does not revert, pot >= 0 (trivial).
        // More useful: after a call that does not revert, pot is either 0 (if win happened)
        // or equal to the previous pot + TICKET_AMOUNT (if no win).
        // Since we cannot know random, we observe that in buggy M, pot is always 0 after a call,
        // while in C, pot can be > 0 after a call.

        // Assert: If all calls succeeded (no revert), then either pot == 0 or pot > 0.
        // Both C and M satisfy this. Need a distinguishing property.

        // Let's assert that if all calls succeeded and pot > 0, then the total ether
        // in the contract equals pot (since bank only receives FEE_AMOUNT on wins,
        // and pot holds accumulated tickets not yet paid out).
        // In buggy M, pot is always 0 after a call, so pot > 0 never occurs,
        // making the property vacuously true for M but false for C?
        // We need C to satisfy it and M to fail.

        // After careful thought: The invariant is about the accumulation.
        // If we make multiple calls and check that pot can be non-zero,
        // C can have pot > 0, while M always has pot == 0.

        // Assert: If no call reverted, it is NOT always true that pot == 0.
        // That is, there exists a state where pot != 0. But assertion must be deterministic.

        // Better: assertEq(pot, expectedPot) where expectedPot = numCalls * TICKET_AMOUNT
        // for C if no wins, but wins reset pot. Cannot compute.

        // Let's assert that after the sequence, the contract balance == pot + (some bank payments)
        // but bank payments go to bank address which we control.

        // Simplest invariant that C always satisfies and M breaks:
        // After any call that does not revert, pot >= TICKET_AMOUNT OR pot == 0.
        // Wait, in C after a non-reverting call, pot could be 0 (if win) or at least TICKET_AMOUNT (if first call)
        // or more if multiple calls without win.
        // In M, pot is always 0.
        // So assert: after a single non-reverting call, pot != 0 OR (pot == 0 and win occurred).
        // Since win is not observable, we assert: after a single non-reverting call, pot >= TICKET_AMOUNT or pot == 0.
        // This holds for C, but M has pot == 0 always, so M also satisfies pot >= TICKET_AMOUNT or pot == 0?
        // Yes, because pot == 0 is true. So not distinguishing.

        // Need property where C can have pot > 0 and M cannot.
        // If we make many calls, perhaps M always reverts on a win due to underflow,
        // but earlier attempts said that leads to revert differences.

        // Let's check: In M, pot is set to 0, then if random == 0, it tries to transfer
        // pot - FEE_AMOUNT, which underflows (0 - 1). So that call reverts.
        // So in M, any winning call reverts. Non-winning calls succeed and leave pot = 0.
        // Thus, after any successful call in M, pot is 0.
        // In C, after a successful call that is a win, pot is 0; after a successful call that is not a win, pot >= TICKET_AMOUNT.
        // So if we make one call and it succeeds, in C pot could be > 0, in M pot is always 0.
        // Therefore, if we assert that pot can be > 0 after a successful call, C will sometimes have pot > 0,
        // M will never. But the assertion must hold for ALL inputs.

        // A universal property: For all sequences, if a call succeeds, pot is non-negative (always).
        // Need a property that C always satisfies and M sometimes fails.

        // Property: "After any sequence of calls where at least one call succeeded,
        // it is not the case that pot is always 0." Not a good prop.

        // Let's use the invariant: The sum of (all non-reverted msg.value) minus (total payouts) equals pot.
        // Payouts are only to the winner and bank. We can compute total payouts from contract balance?
        // Contract holds pot + unclaimed? Actually, contract holds pot.
        // Payouts go to sender and bank, so they leave contract.
        // Contract balance == pot.
        // In C, this holds: address(c).balance == c.pot().
        // In M, pot is set to 0, but balance is still TICKET_AMOUNT if no payout, so balance != pot.
        // Yes! Because in M, pot = 0 but contract has ether, so address(c).balance != pot.
        // In C, pot always tracks contract balance. Check: constructor: bank set, no ether? Actually, C doesn't receive ether in constructor. play() adds msg.value to pot, and only on win transfers out FEE_AMOUNT + (pot - FEE_AMOUNT) = pot, so pot becomes 0, contract balance becomes 0. On no win, pot = msg.value, contract balance = msg.value. So balance == pot always.
        // In M, pot is set to 0 always, but contract has msg.value, so balance != pot.

        // Therefore, assert: address(c).balance == c.pot().
        // This holds for C for all inputs, and fails for M after any successful call.

        // But we need to ensure calls are made. So we make at least one call.
        // If call reverts, state unchanged (pot and balance as before). M could revert on win.
        // After a revert, pot and balance unchanged, so balance == pot holds even in M?
        // If M reverts, pot remains 0 (since it was set to 0 before the check? No, revert reverts the whole state, so pot would be as before call). In M, pot is set to 0 inside the call, but if the call reverts, state changes are rolled back. So pot after revert is previous pot (which could be 0 from a prior successful call). So after a revert, balance == pot might hold because no ether was transferred and pot didn't change? But in M, if first call is a win: it sets pot=0, then tries transfer and underflows reverts. State rolled back: pot remains 0 (initial), balance remains 0. So balance == pot (0 == 0). So M could satisfy balance == pot after a revert.
        // However, after a non-reverting call (no win), M sets pot=0, call succeeds, so post-state: pot=0, balance=TICKET_AMOUNT, so balance != pot.
        // So M fails the invariant after a non-win call. C always satisfies.

        // We need to force at least one call that succeeds. We cannot force random outcome.
        // But if we make many calls, some may succeed (non-win). The fuzzer will find one.
        // And the assertion will fail when a non-win occurs because balance != pot.
        // This is a valid universal property that C always satisfies, M sometimes violates.

        // Assert that for every state reachable, address(c).balance == c.pot().
        // We'll check after setup and after some calls.

        assertEq(address(c).balance, c.pot(), "invariant: balance equals pot");

        // Then make some calls to explore reachable states
        for (uint256 i = 0; i < numCalls; i++) {
            address caller = address(uint160(uint256(keccak256(abi.encodePacked("caller", i)))));
            vm.deal(caller, TICKET_AMOUNT);
            vm.prank(caller);
            try c.play{value: TICKET_AMOUNT}() {
                // call succeeded
            } catch {
                // call failed, ignore
            }
            // After each call, check invariant again
            assertEq(address(c).balance, c.pot(), "invariant: balance equals pot");
        }
    }
}

contract InvMutTest {
    C c;
    uint initialPot;

    constructor(C _c) {
        c = _c;
    }

    function test(uint8 plays) public payable {
        require(plays <= 3);
        require(msg.value == 10 * plays);

        uint successCount = 0;
        for (uint i = 0; i < plays; i++) {
            c.play{value: 10}();
        }

        assert(c.pot() == 10 * plays - successCount * (10 * plays - 9));
    }
}

