import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint256 difficulty) public {
        vm.assume(timestamp < 2**64);
        vm.assume(difficulty < 2**256);

        address player = address(0x1234);
        uint256 ticketAmount = 10;

        vm.warp(timestamp);
        vm.roll(difficulty);

        vm.deal(player, ticketAmount * 2);

        // Play once
        vm.prank(player);
        c.play{value: ticketAmount}();

        bool won;
        // Determine via pot state if first play was a win (pot would be 0 if win occurred)
        uint256 potAfterFirst = c.pot();

        if (potAfterFirst == 0) {
            won = true;
        } else {
            // If pot not zero, either loss or not yet determined
            // Play again with same block params, but different context? Actually random depends on block.timestamp/block.difficulty
            // Let's try playing again and see if we can trigger win
            // For the property, we rely on the fuzzer to find params where first play wins
            // But we can't easily know if win without observing pot.
            // We'll just check the invariant after every play call.
        }

        // Actually, let's use a callback approach: we need to detect win reliably.
        // We can check if pot after call is 0, meaning win happened.
        // This is observable.

        // If potAfterFirst == 0, a win happened, and the invariant says pot should be 0 (which it is).
        // For the buggy version, after a win, pot would not be reset, so pot would remain > 0.
        // But here we just played once, and potAfterFirst == 0 indicates a win (correct reset).
        // To trigger the bug, we need to play, win, then observe pot > 0. That's exactly what the mutant does.

        // So the property is: after any call to play() where pot becomes 0, the pot must be 0.
        // But that's tautological. We need a stronger: if the call resulted in a payout to sender, pot must be 0.
        // Payout to sender occurs when random == 0. We can detect payout by checking player balance increased by (pot_before - FEE_AMOUNT).
        // But pot_before is not stored separately.

        // Simpler: the property is: if after a play call, the contract's ETH balance is 0, then pot must be 0.
        // The contract only holds ETH in pot (no other balances). Actually bank receives fee, player receives rest.
        // After a win, all pot is distributed, so address(c).balance becomes 0.
        // So: after any play, if address(c).balance == 0, then pot must be 0.
        // The bug: after a win, pot is not reset, so address(c).balance == 0 but pot > 0.
        // Let's use that property.

        // To test: we need the fuzzer to find block params that result in random == 0 (win).
        // Then after a win, address(c).balance == 0 (all transferred out), but in the mutant pot > 0.
        // The reference satisfies pot == 0.

        // So we play and check the invariant.

        vm.deal(player, ticketAmount);
        vm.prank(player);
        c.play{value: ticketAmount}();

        if (address(c).balance == 0) {
            assertEq(c.pot(), 0, "pot must be 0 when contract balance is 0");
        } else {
            assertTrue(true); // trivially pass when not a win scenario
        }
    }
}
